select started_at as time, job as metric, job_seconds as value
from metrics.ci_runs where $__timeFilter(started_at) and job in ($job) and outcome in ($outcome)
union all
select started_at, job || ' (10-run average)', avg(job_seconds) over (partition by job order by started_at rows 9 preceding)
from metrics.ci_runs where $__timeFilter(started_at) and job in ($job) and outcome in ($outcome)
order by 1

select started_at as time, job as metric, test_seconds as value
from metrics.ci_runs where $__timeFilter(started_at) and job in ($job) and outcome in ($outcome)
union all
select started_at, job || ' (10-run average)', avg(test_seconds) over (partition by job order by started_at rows 9 preceding)
from metrics.ci_runs where $__timeFilter(started_at) and job in ($job) and outcome in ($outcome)
order by 1
